SELECT b.ProcessInstanceID AS WI_Name , ('Type: '||a.Product||'<br>'|| 'Pricing: '|| a.P_Rate_Type||'<br>'|| 'Effective Interest Rate: '|| a.P_Effec_Int_Rate||'<br>'|| 'Maximun tenor: '|| a.Tenor_In_Months) AS Facilities, ('Request Type: '|| a.Request_Type||'<br>'|| 'Currency: '|| a.Currency)  AS Type_Currency , NVL(TO_CHAR((SELECT LISTAGG(Facility_Purpose,',<br> ') FROM NG_CLOS_Borrower_FacilityPurpose WHERE ChildTableId = a.ParentTableId)),'N/A') AS Purpose,'N/A' AS Existing_Limits,  'N/A' AS Current_Outstanding, TO_CHAR(a.Proposed_Amount_Limit,'999999999999999999999.99') AS Proposed_Amount_Limit, TO_CHAR(a.Proposed_Amount_Limit,'999999999999999999999.99') AS New_Money FROM NG_CLOS_Borrower_NewLoans a, WFINSTRUMENTTABLE  b WHERE a.WI_Name = b.ProcessInstanceID AND (b.ParentWorkItemID IS NULL OR b.ParentWorkItemID = 0) AND b.ProcessInstanceID = '#wi_name#' UNION SELECT b.ProcessInstanceID AS WI_Name , ('Type: '|| a.Product||'<br>'|| 'Pricing: '|| a.P_Rate_Type||'<br>'|| 'Effective Interest Rate: '|| a.P_Effec_Int_Rate|| '<br>'||'Maximun tenor: '|| a.Tenor_In_Months) AS Facilities, ('Request Type: '|| a.Request_Type||'<br>'|| 'Currency: '|| a.Currency) AS Type_Currency, NVL(TO_CHAR((SELECT LISTAGG(Facility_Purpose,',<br> ') FROM NG_CLOS_Borrower_FacilityPurpose WHERE ChildTableId = a.ParentTableId)),'N/A') AS Purpose,TO_CHAR(a.Sanc_Amount,'999999999999999999999.99') AS Existing_Limits, TO_CHAR(a.Current_Outstanding,'999999999999999999999.99') AS Current_Outstanding, TO_CHAR(a.Proposed_Amount_Limit,'999999999999999999999.99') AS Proposed_Amount_Limit, TO_CHAR(a.New_Money,'999999999999999999999.99') AS New_Money FROM NG_CLOS_Borrower_ExistingLoans a, WFINSTRUMENTTABLE b WHERE a.WI_Name = b.ProcessInstanceID AND (b.ParentWorkItemID IS NULL OR b.ParentWorkItemID = 0) AND b.ProcessInstanceID = '#wi_name#'